SESSIONS = {}          # <- 致命:这个 dict 只属于当前进程

def login(username, password):
    if not check_password(username, password):
        return None
    sid = secrets.token_urlsafe(32)
    SESSIONS[sid] = {'user': username, 'ts': time.time()}
    return sid

def whoami(sid):
