import ("context"; "encoding/json"; "time"
        "github.com/redis/go-redis/v9")

var rdb = redis.NewClient(&redis.Options{
    Addr: "127.0.0.1:16380",
})

const sessionTTL = 30 * time.Minute

func login(ctx context.Context, u, p string) (string, error) {
    if !checkPassword(u, p) { return "", ErrAuth }
    sid := randomToken(32)
    b, _ := json.Marshal(Session{User: u})
    // Set 的最后一个参数就是 TTL,等价于 SETEX
    if err := rdb.Set(ctx, "sess:"+sid, b, sessionTTL).Err(); err != nil {
        return "", err
    }
    return sid, nil
}

func whoami(ctx context.Context, sid string) (string, error) {
    b, err := rdb.Get(ctx, "sess:"+sid).Bytes()
    if err == redis.Nil { return "", ErrNoSession }
    if err != nil       { return "", err }   // Redis 挂了要区分处理
    rdb.Expire(ctx, "sess:"+sid, sessionTTL) // 滑动过期
    var s Session
    json.Unmarshal(b, &s)
    return s.User, nil
}
